    public CompletableFuture<Object> modifyMarginHelper(String symbol, Object amount, Object type, Map<String, Object> parameters)
    {

        return BaseExchange.supplyAsync(() -> {

            if (java.util.Objects.equals(this.markets, null))
            {
                (this.loadMarkets(false, new HashMap<String, Object>() {{}})).join();
            }
            String side = this.safeString(parameters, "side");
            Map<String, Object> market = this.market(symbol);
            Map<String, Object> request = new HashMap<String, Object>() {{
                put( "instrument_id", market.get("id") );
                put( "amount", Digifinex.this.numberToString(amount) );
                put( "type", type );
                put( "side", side );
            }};
            Map<String, Object> response = (this.privateSwapPostAccountPositionMargin(this.extend(request, parameters))).join();
            //
            //     {
            //         "code": 0,
            //         "data": {
            //             "instrument_id": "BTCUSDTPERP",
            //             "side": "long",
            //             "type": 1,
            //             "amount": "3.6834"
            //         }
            //     }
            //
            Long code = this.safeInteger(response, "code");
            String status = "failed";
            if ((code != null && code == 0))
            {
                status = "ok";
            }
            Map<String, Object> data = (Map<String, Object>) this.safeDict(response, "data", new HashMap<String, Object>() {{}});
            return this.extend(this.parseMarginModification((Map<String, Object>) (data), market), Helpers.newMap(
                "status", status
            ));
        });

    }

    public Object parseMarginModification(Map<String, Object> data, Map<String, Object> market)
    {
        //
        //     {
        //         "instrument_id": "BTCUSDTPERP",
        //         "side": "long",
        //         "type": 1,
        //         "amount": "3.6834"
        //     }
        //
        String marketId = this.safeString(data, "instrument_id");
        Long rawType = this.safeInteger(data, "type");
        return Helpers.newMap(
            "info", data,
            "symbol", this.safeSymbol(marketId, market, (String) null, "swap"),
            "type", ((((rawType != null && rawType == 1)))) ? "add" : "reduce",
            "marginMode", "isolated",
            "amount", this.safeNumber(data, "amount", (Object) null),
            "total", null,
            "code", this.safeString(market, "settle"),
            "status", null,
            "timestamp", null,
            "datetime", null
        );
    }

